    return { status, issues: column, total: column.length };
  });
}

export async function countIssues(
  orgId: OrgId,
  projectId: ProjectId,
  scope: ArchiveScope = {},
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, scope),
        ),
      ),
    )
    .get();
  return row?.value ?? 0;
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

export async function insertIssue(
  input: CreateIssueInput,
  authorId: UserId,
  issueNumber: number,
): Promise<Issue> {
  const stamp = toIsoTimestamp(new Date());
  const db = getDb();

  const row = db
    .insert(issues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      number: issueNumber,
      title: input.title,
      description: input.description,
      status: input.status,
      priority: input.priority,
      authorId,
      assigneeId: input.assigneeId,
      parentId: input.parentId,
      estimate: input.estimate,
      dueAt: input.dueAt,

/**
 * Invoice history table.
 */
import { Badge } from "@/components/ui/badge";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { formatDate } from "@/lib/date";
import { formatCents } from "@/lib/format";
import type { Invoice } from "@/types/billing";
import type { ReactElement } from "react";

export type InvoiceTableProps = { invoices: readonly Invoice[] };

export function InvoiceTable(props: InvoiceTableProps): ReactElement | null {
  const { invoices } = props;

  if (invoices.length === 0) {
    return (
      <EmptyState
        title="No invoices yet"
        description="Invoices appear here at the end of each billing period."
      />
    );
  }

  // Newest period first — nobody scrolls to the bottom for last month.
  const ordered = [...invoices].sort((a, b) =>
    b.periodStart.localeCompare(a.periodStart),
  );

  return (
    <Table caption="Invoices">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Number</TableHeaderCell>
          <TableHeaderCell>Period</TableHeaderCell>
          <TableHeaderCell>Amount</TableHeaderCell>
          <TableHeaderCell>Status</TableHeaderCell>
        </TableRow>
      </TableHead>

      <TableBody>
        {ordered.map((invoice) => (
          <TableRow key={invoice.id}>
            <TableCell className="font-mono text-sm">
              {invoice.number}
            </TableCell>
            <TableCell>
              {formatDate(invoice.periodStart)} – {formatDate(invoice.periodEnd)}
            </TableCell>
            <TableCell>
              {formatCents(invoice.amountCents, invoice.currency)}
            </TableCell>
            <TableCell>
              {invoice.paidAt === null ? (
                <Badge tone="warning" size="sm">
                  Due
                </Badge>
              ) : (
                <Badge tone="success" size="sm">
                  Paid {formatDate(invoice.paidAt)}
                </Badge>
              )}
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

