14	
15	describe("schemas/billing", () => {
16	  it("accepts exactly the plan ids the domain declares", () => {
17	    for (const plan of PLAN_IDS) {
18	      expect(planIdSchema.safeParse(plan).success, plan).toBe(true);
19	    }
20	    expect(planIdSchema.safeParse("platinum").success).toBe(false);
21	  });
22	
23	  it("accepts only the two billing intervals", () => {
24	    expect(billingIntervalSchema.safeParse("monthly").success).toBe(true);
25	    expect(billingIntervalSchema.safeParse("annual").success).toBe(true);
26	    expect(billingIntervalSchema.safeParse("weekly").success).toBe(false);
27	  });
28	
29	  it("accepts the subscription lifecycle states", () => {
30	    for (const status of ["trialing", "active", "past_due", "canceled"]) {
31	      expect(subscriptionStatusSchema.safeParse(status).success, status).toBe(true);
32	    }
33	    expect(subscriptionStatusSchema.safeParse("paused").success).toBe(false);
34	  });
35	
36	  it("accepts every limited resource dimension", () => {
37	    for (const resource of [
38	      "seats",
39	      "projects",
40	      "issuesPerProject",
41	      "storageMb",
42	      "apiRequestsPerHour",
43	      "webhooks",
44	    ]) {
45	      expect(limitedResourceSchema.safeParse(resource).success, resource).toBe(true);
46	    }
47	    expect(limitedResourceSchema.safeParse("bandwidth").success).toBe(false);
48	  });
