/**
 * Billing period arithmetic: where a period ends, how many days it spans, and
 * how much of a change to prorate into it.
 *
 * A monthly period ends on the same day of the following month at the same
 * time of day, clamped to the month's last day when it has none (31 January
 * → 28 February); an annual period ends on the same day and month a year on.
 * Each new period starts exactly where the previous one ended, so a clamped
 * day carries forward on the next rollover.
 */
import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** The end of a period that starts at `date`, for the given interval. */
export function addInterval(date: Date, interval: BillingInterval): Date {
  return addMonthsClamped(date, monthsInInterval(interval));
}

function addMonthsClamped(date: Date, months: number): Date {
  const totalMonths = date.getUTCFullYear() * 12 + date.getUTCMonth() + months;
  const targetYear = Math.floor(totalMonths / 12);
  const targetMonth = totalMonths % 12;
  const lastDayOfTargetMonth = new Date(
    Date.UTC(targetYear, targetMonth + 1, 0),
  ).getUTCDate();
  const day = Math.min(date.getUTCDate(), lastDayOfTargetMonth);

  return new Date(
    Date.UTC(
      targetYear,
      targetMonth,
      day,
      date.getUTCHours(),
      date.getUTCMinutes(),
      date.getUTCSeconds(),
      date.getUTCMilliseconds(),
    ),
  );
}

/** The full charge for one period: price per seat × seats × months in it. */
export function periodChargeCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/** Whole days spanned by a period, at least one. */
export function daysInPeriod(start: Date, end: Date): number {
  return Math.max(1, Math.round((end.getTime() - start.getTime()) / MS_PER_DAY));
}

/**
 * Whole or started days left between `now` and a period's end — 14 days and
 * 22 hours left counts as 15 — and zero once the end has been reached.
 */
export function daysRemaining(now: Date, periodEnd: Date): number {
  const deltaMs = periodEnd.getTime() - now.getTime();
  return deltaMs <= 0 ? 0 : Math.ceil(deltaMs / MS_PER_DAY);
}

/**
 * Scales a full-period charge by the days left over the days in the period,
 * rounded down to whole cents.
 */
export function prorateCents(
  fullAmountCents: number,
  now: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  const remaining = daysRemaining(now, periodEnd);
  if (remaining === 0) return 0;
  return Math.floor((fullAmountCents * remaining) / daysInPeriod(periodStart, periodEnd));
}

