/**
 * Advances every workspace's subscription period and invoices paid renewals;
 * cancellations whose date has arrived land on the free plan.
 *
 * Must call (do not reimplement): emit, getPlanLimits, issueInvoice
 */
import { getPlanLimits } from "@/config/plan-limits";
import { addInterval, periodChargeCents } from "@/lib/billing-period";
import { parseIso } from "@/lib/date";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "./types";
import type { Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const FREE_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * Sweeps every live workspace. An `active` subscription past its period end
 * catches up one period at a time, each paid one invoiced at today's seat
 * count, until the period ends after `now`. A `canceled` subscription whose
 * cancellation date has arrived moves to the free plan instead, with no
 * invoice. Trialing and past-due subscriptions are left for the trial-expiry
 * job. Re-running at the same instant is a no-op: once a period ends after
 * `now`, or a cancellation has already landed on `free`, there is nothing
 * left to advance.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const stamp = toIsoTimestamp(now);
    const orgs = await orgRepo.listAllOrgs();

    for (const org of orgs) {
      try {
        const subscription = await subscriptionRepo.findSubscription(org.id);
        if (!subscription) continue;

        if (subscription.status === "active") {
          const renewed = await renewSubscription(org.id, subscription, now);
          if (renewed) result.processed += 1;
        } else if (
          subscription.status === "canceled" &&
          subscription.cancelAt !== null &&
          subscription.cancelAt <= stamp
        ) {
          await endCancellation(org.id, subscription, stamp);
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed for workspace", {
          orgId: org.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function renewSubscription(
  orgId: OrgId,
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  let periodStart = parseIso(subscription.currentPeriodStart);
  let periodEnd = parseIso(subscription.currentPeriodEnd);
  let renewed = false;

  while (periodEnd.getTime() <= now.getTime()) {
    periodStart = periodEnd;
    periodEnd = addInterval(periodStart, subscription.interval);
    renewed = true;

    if (subscription.plan !== FREE_PLAN) {
      const amountCents = periodChargeCents(
        getPlanLimits(subscription.plan).priceCentsPerSeatMonthly,
        subscription.seats,
        subscription.interval,
      );
      if (amountCents > 0) {
        await issueInvoice(
          orgId,
          toIsoTimestamp(periodStart),
          toIsoTimestamp(periodEnd),
          amountCents,
          null,
        );
      }
    }
  }

  if (renewed) {
    await subscriptionRepo.setCurrentPeriod(
      orgId,
      toIsoTimestamp(periodStart),
      toIsoTimestamp(periodEnd),
    );
  }

  return renewed;
}

async function endCancellation(
  orgId: OrgId,
  subscription: Subscription,
  effectiveAt: IsoTimestamp,
): Promise<void> {
  const periodEnd = toIsoTimestamp(addInterval(parseIso(effectiveAt), "monthly"));
  await subscriptionRepo.applyCancellation(orgId, effectiveAt, periodEnd);

  await emit("billing.plan_changed", {
    orgId,
    actorId: null,
    occurredAt: effectiveAt,
    from: subscription.plan,
    to: FREE_PLAN,
  });
}

