  const org2 = await orgRepo.insertOrg({ name: "Beta", slug: "beta", plan: "growth" }, owner2.id);
  await subscriptionRepo.insertSubscription(org2.id, "growth", "monthly");
  await memberRepo.insertMember(org2.id, owner2.id, "owner", null);
  await subscriptionRepo.cancelSubscription(org2.id, null);
  const cancelAt = toIsoTimestamp(new Date("2026-05-10T00:00:00.000Z"));
  await subscriptionRepo.cancelSubscription(org2.id, cancelAt);

  const planChangedEvents: unknown[] = [];
  subscribe("billing.plan_changed", (p) => { planChangedEvents.push(p); });

  await runBillingRenewalJob(now);
  const sub2 = await subscriptionRepo.findSubscription(org2.id);
  console.log("cancelled sub after job:", sub2);
  console.log("plan_changed events:", planChangedEvents.length);

  await runBillingRenewalJob(now);
  console.log("plan_changed events after replay (expect same):", planChangedEvents.length);

  // --- updateSeats proration ---
  const owner3 = await userRepo.insertUser({ email: "o3@x.test", name: "Owner3", passwordHash: "x" });
  const org3 = await orgRepo.insertOrg({ name: "Gamma", slug: "gamma", plan: "starter" }, owner3.id);
  await subscriptionRepo.insertSubscription(org3.id, "starter", "monthly");
  await memberRepo.insertMember(org3.id, owner3.id, "owner", null);
  await subscriptionRepo.cancelSubscription(org3.id, null);
  await subscriptionRepo.setCurrentPeriod(
    org3.id,
    toIsoTimestamp(new Date("2026-05-01T00:00:00.000Z")),
    toIsoTimestamp(new Date("2026-06-01T00:00:00.000Z")),
  );
  const actor3 = { userId: owner3.id, orgId: org3.id, role: "owner" as const };

  const invBefore = (await invoiceRepo.listInvoices(org3.id)).length;
  await billingService.updateSeats(actor3, { orgId: org3.id, seats: 5 });
  const invAfterAdd = await invoiceRepo.listInvoices(org3.id);
  console.log("invoices after adding seats:", invAfterAdd.length - invBefore, invAfterAdd);

  await billingService.updateSeats(actor3, { orgId: org3.id, seats: 2 });
  const invAfterRemove = await invoiceRepo.listInvoices(org3.id);
  console.log("invoices after removing seats (expect no new):", invAfterRemove.length - invAfterAdd.length);

  console.log("ALL CHECKS DONE");
}

main().catch((e) => { console.error(e); process.exit(1); });
