import { toIsoTimestamp } from "@/types/common";

async function main() {
  await runMigrations(process.env.TASKFLOW_DB_PATH!);

  const now = new Date();
  const periodStart = new Date(now.getTime() - 15 * 24 * 60 * 60 * 1000);
  const periodEnd = new Date(now.getTime() + 15 * 24 * 60 * 60 * 1000); // 30-day period, 15 left

  const owner3 = await userRepo.insertUser({ email: "o3@x.test", name: "Owner3", passwordHash: "x" });
  const org3 = await orgRepo.insertOrg({ name: "Gamma", slug: "gamma", plan: "starter" }, owner3.id);
  await subscriptionRepo.insertSubscription(org3.id, "starter", "monthly");
  await memberRepo.insertMember(org3.id, owner3.id, "owner", null);
  await subscriptionRepo.cancelSubscription(org3.id, null);
  await subscriptionRepo.setCurrentPeriod(org3.id, toIsoTimestamp(periodStart), toIsoTimestamp(periodEnd));
  const actor3 = { userId: owner3.id, orgId: org3.id, role: "owner" as const };

  // starter = 900 cents/seat/mo. Adding 4 seats: 900*4=3600 full, 15/30 days -> 1800 cents prorated.
  await billingService.updateSeats(actor3, { orgId: org3.id, seats: 5 });
  const inv1 = await invoiceRepo.listInvoices(org3.id);
  console.log("after adding 4 seats, invoices:", inv1.map(i => ({ amount: i.amountCents, number: i.number })), "(expect one invoice amount=1800)");

  await billingService.updateSeats(actor3, { orgId: org3.id, seats: 2 });
  const inv2 = await invoiceRepo.listInvoices(org3.id);
  console.log("after removing seats, invoice count (expect same as before):", inv2.length);

  // changePlan: paid->paid upgrade starter(900)->growth(1900), diff=1000/seat, seats=2, prorated 15/30 => 1000*2*0.5=1000
  await billingService.changePlan(actor3, { orgId: org3.id, plan: "growth", interval: "monthly" });
  const inv3 = await invoiceRepo.listInvoices(org3.id);
  console.log("after upgrade plan, invoices:", inv3.map(i => ({ amount: i.amountCents, number: i.number })));
  const subAfterUpgrade = await subscriptionRepo.findSubscription(org3.id);
  console.log("period unchanged after upgrade?", subAfterUpgrade?.currentPeriodStart === toIsoTimestamp(periodStart), subAfterUpgrade?.currentPeriodEnd === toIsoTimestamp(periodEnd));

  // downgrade growth->starter: no charge
  const before4 = (await invoiceRepo.listInvoices(org3.id)).length;
  await billingService.changePlan(actor3, { orgId: org3.id, plan: "starter", interval: "monthly" });
  const inv4 = await invoiceRepo.listInvoices(org3.id);
  console.log("after downgrade, new invoices (expect 0):", inv4.length - before4);

  // moving to free: no charge
  const before5 = (await invoiceRepo.listInvoices(org3.id)).length;
  await billingService.changePlan(actor3, { orgId: org3.id, plan: "free", interval: "monthly" });
  const inv5 = await invoiceRepo.listInvoices(org3.id);
  console.log("after moving to free, new invoices (expect 0):", inv5.length - before5);
  const subFree = await subscriptionRepo.findSubscription(org3.id);
  console.log("plan now free, period unchanged?", subFree?.plan, subFree?.currentPeriodStart === toIsoTimestamp(periodStart));

  // free -> paid: fresh period + full invoice
  const before6 = (await invoiceRepo.listInvoices(org3.id)).length;
  await billingService.changePlan(actor3, { orgId: org3.id, plan: "enterprise", interval: "annual" });
  const inv6 = await invoiceRepo.listInvoices(org3.id);
  const subEnt = await subscriptionRepo.findSubscription(org3.id);
  console.log("free->paid new invoices (expect 1):", inv6.length - before6, "latest amount (expect 3900*seats*12):", inv6[0]);
  console.log("new period start ~ now?", subEnt?.currentPeriodStart, "interval:", subEnt?.interval);

  // trial plan swap: charges nothing, keeps period
  const owner4 = await userRepo.insertUser({ email: "o4@x.test", name: "Owner4", passwordHash: "x" });
  const org4 = await orgRepo.insertOrg({ name: "Delta", slug: "delta", plan: "starter" }, owner4.id);
  const trialSub = await subscriptionRepo.insertSubscription(org4.id, "starter", "monthly");
  await memberRepo.insertMember(org4.id, owner4.id, "owner", null);
  console.log("trial sub status:", trialSub.status, "period:", trialSub.currentPeriodStart, trialSub.currentPeriodEnd);
  const actor4 = { userId: owner4.id, orgId: org4.id, role: "owner" as const };
  await billingService.changePlan(actor4, { orgId: org4.id, plan: "growth", interval: "monthly" });
  const inv7 = await invoiceRepo.listInvoices(org4.id);
  const subAfterTrialChange = await subscriptionRepo.findSubscription(org4.id);
  console.log("trial plan change invoices (expect 0):", inv7.length);
  console.log("trial period kept?", subAfterTrialChange?.currentPeriodStart === trialSub.currentPeriodStart, subAfterTrialChange?.currentPeriodEnd === trialSub.currentPeriodEnd, "status now:", subAfterTrialChange?.status);

  console.log("DONE");
}

main().catch((e) => { console.error(e); process.exit(1); });
