import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

process.env.TASKFLOW_DB_PATH = join(mkdtempSync(join(tmpdir(), "taskflow-check3-")), "db.sqlite");

import { runMigrations } from "@/server/db/migrate";
import * as userRepo from "@/server/repositories/user-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as billingService from "@/server/services/billing-service";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import { toIsoTimestamp } from "@/types/common";

async function main() {
  await runMigrations(process.env.TASKFLOW_DB_PATH!);
  registerEventHandlers();

  const now = new Date();
  const periodStart = new Date(now.getTime() - 15 * 24 * 60 * 60 * 1000);
  const periodEnd = new Date(now.getTime() + 15 * 24 * 60 * 60 * 1000);

  const owner = await userRepo.insertUser({ email: "o@x.test", name: "Owner", passwordHash: "x" });
  const org = await orgRepo.insertOrg({ name: "Acme", slug: "acme", plan: "starter" }, owner.id);
  await subscriptionRepo.insertSubscription(org.id, "starter", "monthly");
  await memberRepo.insertMember(org.id, owner.id, "owner", null);
  await subscriptionRepo.cancelSubscription(org.id, null);
  await subscriptionRepo.setCurrentPeriod(org.id, toIsoTimestamp(periodStart), toIsoTimestamp(periodEnd));
  const actor = { userId: owner.id, orgId: org.id, role: "owner" as const };

  await billingService.updateSeats(actor, { orgId: org.id, seats: 5 });

  await new Promise((r) => setTimeout(r, 50)); // let async subscribers settle

  const activity = await activityRepo.listActivity({ orgId: org.id, limit: 20, cursor: null });
  console.log("activity rows:", activity.items.map(a => ({ action: a.action, summary: a.summary, actorId: a.actorId })));

  const notifications = await notificationRepo.listNotifications({ orgId: org.id, recipientId: owner.id, limit: 20, cursor: null, unreadOnly: false });
  console.log("notifications for owner (actor=owner, should be 0 since actor==owner is excluded):", notifications.items.length);

  // Now issue via the job (actor = null) and check owner IS notified
  const owner2 = await userRepo.insertUser({ email: "o2@x.test", name: "Owner2", passwordHash: "x" });
  const org2 = await orgRepo.insertOrg({ name: "Beta", slug: "beta", plan: "starter" }, owner2.id);
  await subscriptionRepo.insertSubscription(org2.id, "starter", "monthly");
  await memberRepo.insertMember(org2.id, owner2.id, "owner", null);
  await subscriptionRepo.cancelSubscription(org2.id, null);
  await subscriptionRepo.setCurrentPeriod(org2.id, toIsoTimestamp(new Date(now.getTime() - 40*24*60*60*1000)), toIsoTimestamp(new Date(now.getTime() - 1000)));

  const { runBillingRenewalJob } = await import("@/server/jobs/billing-renewal-job");
  await runBillingRenewalJob(now);

  await new Promise((r) => setTimeout(r, 50));

  const notifications2 = await notificationRepo.listNotifications({ orgId: org2.id, recipientId: owner2.id, limit: 20, cursor: null, unreadOnly: false });
  console.log("notifications for owner2 after job-driven invoice (expect 1, kind invoice_issued):", notifications2.items.map(n => ({ kind: n.kind, title: n.title })));

  const activity2 = await activityRepo.listActivity({ orgId: org2.id, limit: 20, cursor: null });
  console.log("activity rows org2:", activity2.items.map(a => ({ action: a.action, summary: a.summary })));

  console.log("DONE");
}

main().catch((e) => { console.error(e); process.exit(1); });
EOF
